(932, 'siteorigin_custom_css[storefront]', '.site-header-cart .cart-contents {\r\n  display: none;\r\n}\r\n\r\n\r\n\r\n.site-info {\r\n  display: none;\r\n}\r\n\r\n.price_label {\r\n  text-decoration: none;\r\n  font-weight: bold;\r\n  color: #37686b;\r\n  text-align: left;\r\n  font-size: 17px;\r\n}\r\n\r\n.widget_price_filter .price_slider_amount .button {\r\n  text-align: center;\r\n  text-indent: 0cm;\r\n  font-size: 26px;\r\n  line-height: 9px;\r\n  font-variant: normal;\r\n  letter-spacing: 0px;\r\n  font-weight: bold;\r\n  word-spacing: 0px;\r\n}\r\n\r\n.storefront-breadcrumb {\r\n  margin-bottom: -5px;\r\n}\r\n\r\n.gallery-item {margin-top: 20px;}\r\n\r\n.row { margin-left: 0px !important; margin-right: 0px !important; }\r\nfooter { background: rgba(219, 176, 0, .1); padding: 40px 0px ;}\r\n.footer__phone { color: #D11D1D; text-align: center; }\r\n.footer__phone a,.footer__phone h3 { text-decoration: none; font-family: \'Tahoma\', sans-serif; font-weight: 700; font-size: 2.9rem; }\r\n.footer__phone h4, .accent { font-family: \'Roboto Slab\', sans-serif; font-weight: 400; font-size: 2.1rem; }\r\n.copyright p { font-family: \'Tahoma\', sans-serif; font-weight: 400; font-size: 1rem; text-align: center; color: #293C3D; }\r\n.footer__menu a { font-family: \'Tahoma\', sans-serif; font-weight: 400; font-size: 1.2rem; text-align: center; color: #293C3D; }\r\n.footer__logo p { font-family: \'Tahoma\', sans-serif; font-weight: 400; font-size: 1.2rem; text-align: center; color: #293C3D; }\r\n.footer__menu li { list-style: none; }\r\n\r\n.header__phone__div { display: flex; flex-direction: row; justify-content: center; align-items: center; margin: 20px 0; }\r\n.header__phone__div a { font-size: 18px !important; }\r\n\r\n.whatsapp__button { display: block; min-width: 192px; background: #00e676; color: #fff !important; text-decoration: none !important; padding: 2px 20px; text-align: center; margin-left: 15px; }\r\n.fa-whatsapp { color: #00e676; }\r\n\r\n.footer-email {\r\n  font-size: 18px !important;\r\n  margin-top: 20px;\r\n}\r\n\r\n.lastposts {\r\n  margin-bottom: 60px;\r\n}\r\n\r\n.lastposts__title {\r\n  text-align: center;\r\n}\r\n\r\n.lastposts__inner {\r\n  display: flex;\r\n  margin: 0 -20px -20px;\r\n}\r\n\r\n.lastposts__item {\r\n  flex-shrink: 0;\r\n  flex-basis: 100%;\r\n  box-sizing: border-box;\r\n  padding: 0 20px;\r\n  margin-bottom: 20px;\r\n}\r\n\r\n.lastposts__more {\r\n  text-align: right;\r\n  margin-top: 30px;\r\n}\r\n\r\n.lastposts__morelink {\r\n}\r\n\r\n.post-card {\r\n}\r\n\r\n.post-card__title {\r\n  font-size: 22px;\r\n  margin-bottom: 20px;\r\n}\r\n\r\n.post-card__date {\r\n  font-size: 14px;\r\n  color: #666;\r\n  margin-bottom: 20px;\r\n}\r\n\r\n.post-card__content {\r\n  font-size: 16px;\r\n  margin-bottom: 20px;\r\n}\r\n\r\n.post-card__more {\r\n  text-align: right;\r\n}\r\n\r\n.post-card__morelink {\r\n  text-align: right;\r\n}\r\n\r\n@media all and (min-width: 960px) {\r\n  .lastposts__item {\r\n    flex-basis: 33.333%;\r\n    max-width: 33.333%;\r\n  }\r\n}', 'no');
