(91307, '_site_transient_implecode_extensions_data', 'a:41:{i:0;a:5:{s:3:\"url\";s:15:\"premium-support\";s:4:\"name\";s:15:\"Premium Toolset\";s:4:\"desc\";s:140:\"Product sidebar, product tags, enhanced category widget and premium email support. Premium support is also included in all other extensions.\";s:4:\"comp\";s:6:\"simple\";s:4:\"slug\";s:25:\"implecode-product-sidebar\";}i:1;a:5:{s:3:\"url\";s:24:\"product-gallery-advanced\";s:4:\"name\";s:24:\"Product Gallery Advanced\";s:4:\"desc\";s:116:\"Add unlimited number of product images and show them in a robust product slider or beautiful light-box presentation.\";s:4:\"comp\";s:6:\"simple\";s:4:\"slug\";s:24:\"product-gallery-advanced\";}i:2;a:5:{s:3:\"url\";s:23:\"product-page-customizer\";s:4:\"name\";s:23:\"Product Page Customizer\";s:4:\"desc\";s:131:\"Customize product page with simple settings. Change product page elements, their size, position and colors easily in a few seconds.\";s:4:\"comp\";s:6:\"simple\";s:4:\"slug\";s:23:\"product-page-customizer\";}i:3;a:5:{s:3:\"url\";s:13:\"shopping-cart\";s:4:\"name\";s:13:\"Shopping Cart\";s:4:\"desc\";s:113:\"Full featured shopping cart with advanced customisation options. Transform your product catalog into a Web Store!\";s:4:\"comp\";s:6:\"simple\";s:4:\"slug\";s:23:\"implecode-shopping-cart\";}i:4;a:5:{s:3:\"url\";s:10:\"quote-cart\";s:4:\"name\";s:10:\"Quote Cart\";s:4:\"desc\";s:128:\"Allow your users to send a quote for multiple products. Quote Cart adds a store like experience even for products without price!\";s:4:\"comp\";s:6:\"simple\";s:4:\"slug\";s:20:\"implecode-quote-cart\";}i:5;a:5:{s:3:\"url\";s:15:\"auction-manager\";s:4:\"name\";s:15:\"Auction Manager\";s:4:\"desc\";s:78:\"Set auctions with Quote Cart. Adds a price bid field for the Quote Cart button\";s:4:\"comp\";s:6:\"simple\";s:4:\"slug\";s:15:\"auction-manager\";}i:6;a:5:{s:3:\"url\";s:12:\"color-picker\";s:4:\"name\";s:12:\"Color Picker\";s:4:\"desc\";s:59:\"Display a color picker connected to separate product image.\";s:4:\"comp\";s:6:\"simple\";s:4:\"slug\";s:20:\"product-color-picker\";}i:7;a:5:{s:3:\"url\";s:21:\"catalog-users-manager\";s:4:\"name\";s:21:\"Catalog Users Manager\";s:4:\"desc\";s:78:\"Manage catalog visibility options depending on logged in or anonymous visitor.\";s:4:\"comp\";s:6:\"simple\";s:4:\"slug\";s:21:\"catalog-users-manager\";}i:8;a:5:{s:3:\"url\";s:15:\"multiple-prices\";s:4:\"name\";s:16:\"Multiple Pricing\";s:4:\"desc\";s:84:\"Set multiple, automatically calculated or manually inserted prices for each product.\";s:4:\"comp\";s:6:\"simple\";s:4:\"slug\";s:22:\"multiple-product-price\";}i:9;a:5:{s:3:\"url\";s:16:\"empty-categories\";s:4:\"name\";s:16:\"Empty Categories\";s:4:\"desc\";s:68:\"Show empty categories and add custom text instead of a product list.\";s:4:\"comp\";s:6:\"simple\";s:4:\"slug\";s:16:\"empty-categories\";}i:10;a:5:{s:3:\"url\";s:15:\"listing-buttons\";s:4:\"name\";s:15:\"Listing Buttons\";s:4:\"desc\";s:62:\"Easily add fully customizable buttons to your product listing.\";s:4:\"comp\";s:6:\"simple\";s:4:\"slug\";s:23:\"product-listing-buttons\";}i:11;a:5:{s:3:\"url\";s:14:\"paypal-gateway\";s:4:\"name\";s:14:\"PayPal Gateway\";s:4:\"desc\";s:106:\"Boost the conversion rate with a robust PayPal shopping cart, buy now button or order form implementation.\";s:4:\"comp\";s:6:\"simple\";s:4:\"slug\";s:24:\"implecode-paypal-gateway\";}i:12;a:5:{s:3:\"url\";s:17:\"2checkout-gateway\";s:4:\"name\";s:17:\"2Checkout Gateway\";s:4:\"desc\";s:49:\"Take credit card payments with 2Checkout Gateway.\";s:4:\"comp\";s:6:\"simple\";s:4:\"slug\";s:17:\"2checkout-gateway\";}i:13;a:5:{s:3:\"url\";s:17:\"authorize-net-aim\";s:4:\"name\";s:25:\"Authorize.Net AIM Gateway\";s:4:\"desc\";s:87:\"Take credit card payments with Authorize.Net AIM Gateway. 100% on-site user experience!\";s:4:\"comp\";s:6:\"simple\";s:4:\"slug\";s:17:\"authorize-net-aim\";}i:14;a:5:{s:3:\"url\";s:17:\"authorize-net-sim\";s:4:\"name\";s:25:\"Aut