(91309, '_site_transient_implecode_epc_free_extensions_data', 'a:3:{i:0;a:6:{s:3:\"url\";s:12:\"reviews-plus\";s:4:\"name\";s:15:\"Product Reviews\";s:4:\"desc\";s:80:\"Add reviews support for your catalog items. Use it for all or selected products.\";s:4:\"comp\";s:6:\"simple\";s:4:\"slug\";s:12:\"reviews-plus\";s:4:\"type\";s:4:\"free\";}i:1;a:6:{s:3:\"url\";s:13:\"mailer-dragon\";s:4:\"name\";s:18:\"Catalog Newsletter\";s:4:\"desc\";s:52:\"Let users subscribe for product-related newsletters.\";s:4:\"comp\";s:6:\"simple\";s:4:\"slug\";s:13:\"mailer-dragon\";s:4:\"type\";s:4:\"free\";}i:2;a:6:{s:3:\"url\";s:31:\"catalog-booster-for-woocommerce\";s:4:\"name\";s:19:\"WooCommerce Catalog\";s:4:\"desc\";s:57:\"Display WooCommerce products with product catalog layout.\";s:4:\"comp\";s:6:\"simple\";s:4:\"slug\";s:31:\"catalog-booster-for-woocommerce\";s:4:\"type\";s:4:\"free\";}}', 'no'),
